/**
 * Shape of `site/src/design/tokens.json` — the single design-token file (REQUIREMENTS §6.4 "実装上の担保").
 * Values are generated by Haiku and reviewed by Luna (WP-2.6, `harness/src/design/`); this schema and the
 * machine check (WP-2.7, `harness/src/design/checkTokens.ts`) are code. CSS and SVG must take every color,
 * font size, spacing, radius, line width, breakpoint and duration from here (no literals elsewhere).
 */
export type Hex = string; // "#rrggbb"
/** A color is a hex value or a reference to a UI color key ("bg" | "text" | "sub" | "accent"). */
export type ColorRef = Hex | "bg" | "text" | "sub" | "accent";

export interface DesignTokens {
  schema: "sfsh-tokens/1";
  /** UI: achromatic 3 tones (bg / body text / rules+secondary text) + 1 accent. Light theme only (v1). */
  color: { bg: Hex; text: Hex; sub: Hex; accent: Hex };
  semantic: {
    /** Epistemic classes (2.3): 4 colors + label + mark (never color alone). */
    epistemic: Record<"canon" | "consensus" | "fan_theory" | "sfsh_analysis", { color: Hex; label: string; mark: string }>;
    /** Relation polarity: positive / negative are the 2 polarity colors; ambivalent / neutral are achromatic refs. Line style always differs. */
    valence: Record<"positive" | "negative" | "ambivalent" | "neutral", { color: ColorRef; dash: string; label: string }>;
    /** Knowledge states (figure C): symbol + color (color may reference any palette color). */
    know_state: Record<"unknown" | "suspects" | "misbelieves" | "knows", { color: ColorRef; mark: string; label: string }>;
  };
  font: {
    /** OS fonts only (no web fonts). */
    family: string;
    /** ≤ 4 steps. Keys are fixed. body ≥ 16, small ≥ 13 (figure text uses small). */
    size: { small: number; body: number; h2: number; h1: number };
    /** ≤ 2 weights. */
    weight: { regular: number; bold: number };
    /** body 1.7–1.8. */
    lineHeight: { body: number; heading: number };
  };
  /** 8px base, 4px steps allowed. */
  space: { xs: number; s: number; m: number; l: number; xl: number; section: number };
  /** Single corner radius ≤ 4. */
  radius: number;
  /** Line widths for rules and figure strokes. */
  line: { hair: number; figure: number; strong: number };
  layout: { textMax: number; figureMax: number; tap: number; tapGap: number; sectionGap: number; figureGap: number; gutter: number };
  /** Width classes: smartphone < tablet ≤ … < pc. */
  breakpoint: { tablet: number; pc: number };
  motion: { durationMs: number };
}
